import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0L
        while (c > 32) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return if (sign == 1) result else -result
    }
}

private fun modPow(baseValue: Long, exponentValue: Long, mod: Long): Long {
    var base = baseValue % mod
    var exponent = exponentValue
    var result = 1L

    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = result * base % mod
        }
        base = base * base % mod
        exponent = exponent shr 1
    }
    return result
}

private fun multiplicativeOrder(a: Long, p: Long): Long {
    var order = p - 1
    var remaining = p - 1
    var divisor = 2L

    while (divisor * divisor <= remaining) {
        if (remaining % divisor == 0L) {
            while (remaining % divisor == 0L) {
                remaining /= divisor
            }
            while (order % divisor == 0L &&
                modPow(a, order / divisor, p) == 1L
            ) {
                order /= divisor
            }
        }
        divisor++
    }

    if (remaining > 1L) {
        while (order % remaining == 0L &&
            modPow(a, order / remaining, p) == 1L
        ) {
            order /= remaining
        }
    }

    return order
}

fun main() {
    val scanner = FastScanner()
    val a = scanner.nextLong()
    val b = scanner.nextLong()
    val p = scanner.nextLong()
    val x = scanner.nextLong()

    val order = multiplicativeOrder(a, p)
    val period = p * order
    val completePeriods = x / period
    val remainder = x % period

    var answer = completePeriods * order
    val inverseA = modPow(a, p - 2, p)
    var residueModP = b

    var k = 0L
    while (k < order) {
        var t = (k - residueModP) % order
        if (t < 0L) t += order

        val smallestN = residueModP + p * t
        if (smallestN <= remainder) {
            answer++
        }

        residueModP = residueModP * inverseA % p
        k++
    }

    print(answer)
}

