private fun modInverse(value: Long, mod: Long): Long {
    var a = value
    var b = mod
    var x0 = 1L
    var x1 = 0L

    while (b != 0L) {
        val q = a / b

        val nextA = a - q * b
        a = b
        b = nextA

        val nextX = x0 - q * x1
        x0 = x1
        x1 = nextX
    }

    return ((x0 % mod) + mod) % mod
}

private fun multiplicativeOrder(a: Long, p: Long): Long {
    var order = p - 1
    var remaining = p - 1
    var factor = 2L

    while (factor * factor <= remaining) {
        if (remaining % factor == 0L) {
            while (remaining % factor == 0L) {
                remaining /= factor
            }
            while (order % factor == 0L &&
                modPow(a, order / factor, p) == 1L
            ) {
                order /= factor
            }
        }
        factor++
    }

    if (remaining > 1L) {
        while (order % remaining == 0L &&
            modPow(a, order / remaining, p) == 1L
        ) {
            order /= remaining
        }
    }

    return order
